# MSC Figure 4 - stateful stepped-drive hysteresis
# Standalone plotting script for outputs of MSC_Figure4_reproducible.ipynb.
# Usage: source('figure4_final_v3.r') after setwd() to 04_r_input,
# or: Rscript figure4_final_v3.r /path/to/04_r_input
# Exports PDF, PNG, SVG and TIFF for Figure 4 panels A-E and a combined preview.

req <- c('ggplot2','dplyr','tidyr','readr','scales','patchwork')
miss <- req[!vapply(req, requireNamespace, logical(1), quietly=TRUE)]
if(length(miss)) install.packages(miss, repos='https://cloud.r-project.org')
for(x in c('ragg','svglite')) if(!requireNamespace(x,quietly=TRUE)) try(install.packages(x,repos='https://cloud.r-project.org'),silent=TRUE)
suppressPackageStartupMessages({library(ggplot2);library(dplyr);library(tidyr);library(readr);library(scales);library(patchwork)})
have_ragg <- requireNamespace('ragg',quietly=TRUE); have_svg <- requireNamespace('svglite',quietly=TRUE)
a <- commandArgs(trailingOnly=TRUE); IN <- if(length(a)&&nzchar(a[1])) a[1] else getwd(); OUT <- file.path(IN,'R_output_figure4_v3')
for(x in c('pdf','png','svg','tiff','plotted_data')) dir.create(file.path(OUT,x),recursive=TRUE,showWarnings=FALSE)
p <- function(x) file.path(IN,x)
need <- c('msc_feedback_hysteresis_raw.csv','msc_feedback_hysteresis_summary.csv','msc_feedback_hysteresis_drive_gaps.csv','msc_feedback_hysteresis_seed_statistics.csv','msc_feedback_hysteresis_wilcoxon_tests.csv')
if(any(!file.exists(p(need)))) stop('Missing: ',paste(need[!file.exists(p(need))],collapse=', '))
raw <- read_csv(p(need[1]),show_col_types=FALSE); sm <- read_csv(p(need[2]),show_col_types=FALSE); gaps <- read_csv(p(need[3]),show_col_types=FALSE); ss <- read_csv(p(need[4]),show_col_types=FALSE); wt <- read_csv(p(need[5]),show_col_types=FALSE)
if(n_distinct(raw$seed)!=100 || nrow(raw)!=2200 || !isTRUE(all.equal(sort(unique(raw$activation_amp)),seq(0,1,.1)))) stop('Expected canonical 100-seed, 0-1.0 Figure 4 inputs.')
cat('Validated: 100 seeds, 2200 raw records.\n')

up <- '#3B82B4'; down <- '#D84A3A'; cs <- '#8064A2'; cm <- '#238B57'; ink <- '#252525'; grey <- '#8B8B8B'
th <- function(s=8.2) theme_classic(base_size=s,base_family='sans')+theme(axis.line=element_line(colour=ink,linewidth=.42),axis.ticks=element_line(colour=ink,linewidth=.38),axis.ticks.length=grid::unit(1.4,'mm'),axis.text=element_text(colour=ink,size=s),axis.title=element_text(colour=ink,size=s+.5),axis.title.x=element_text(margin=margin(t=5)),axis.title.y=element_text(margin=margin(r=5)),legend.position='top',legend.title=element_blank(),legend.text=element_text(colour=ink,size=s-.2),legend.key.width=grid::unit(6,'mm'),legend.key.height=grid::unit(3,'mm'),panel.grid.major.y=element_line(colour='#E6E6E6',linewidth=.3),panel.grid.minor=element_blank(),plot.margin=margin(4,4,3,4))

# A: stateful protocol schematic
A <- ggplot()+annotate('segment',x=.12,xend=.47,y=.22,yend=.80,colour=up,linewidth=1.05,arrow=grid::arrow(type='closed',length=grid::unit(2.2,'mm')))+annotate('segment',x=.53,xend=.88,y=.80,yend=.22,colour=down,linewidth=1.05,arrow=grid::arrow(type='closed',length=grid::unit(2.2,'mm')))+geom_point(data=tibble(x=c(.1,.5,.9),y=c(.18,.84,.18)),aes(x,y),shape=21,size=5.4,stroke=.75,fill='#DEE5F2',colour='#34466B')+annotate('text',x=.27,y=.53,label='Ramp up',colour=up,fontface='bold',size=2.7)+annotate('text',x=.73,y=.53,label='Ramp down',colour=down,fontface='bold',size=2.7)+annotate('label',x=.5,y=1.02,label='Same activation drive\ncan encode different histories',size=2.65,fill='#FCF8EE',linewidth=0,label.padding=grid::unit(1.7,'mm'))+annotate('text',x=.1,y=.04,label='Low',size=2.7)+annotate('text',x=.5,y=.04,label='High',size=2.7)+annotate('text',x=.9,y=.04,label='Low',size=2.7)+annotate('text',x=.5,y=-.1,label='Activation drive',size=2.9)+coord_cartesian(xlim=c(0,1),ylim=c(-.16,1.1),clip='off')+theme_void(base_family='sans')

sp <- sm %>% mutate(label=factor(direction,levels=c('up','down'),labels=c('Ramp up','Ramp down')))
w <- sm %>% select(direction,activation_amp,S_mean,M_mean) %>% pivot_wider(names_from=direction,values_from=c(S_mean,M_mean),names_sep='_') %>% arrange(activation_amp) %>% mutate(S_gap=S_mean_down-S_mean_up,M_gap=M_mean_down-M_mean_up)
dS <- max(w$S_gap); dM <- max(w$M_gap); xS <- w$activation_amp[which.max(w$S_gap)]; xM <- w$activation_amp[which.max(w$M_gap)]
branch <- function(st,ytitle,dv,xv){mc<-paste0(st,'_mean');sc<-paste0(st,'_sem'); yu<-w[[paste0(st,'_mean_up')]][w$activation_amp==xv]; yd<-w[[paste0(st,'_mean_down')]][w$activation_amp==xv]; ggplot(sp,aes(activation_amp,.data[[mc]],colour=label,fill=label,group=label))+geom_hline(yintercept=.5,linetype='22',colour=grey,linewidth=.38)+geom_ribbon(aes(ymin=.data[[mc]]-.data[[sc]],ymax=.data[[mc]]+.data[[sc]]),alpha=.15,colour=NA)+geom_line(linewidth=.9)+geom_point(size=1.65)+annotate('segment',x=xv,xend=xv,y=yu,yend=yd,linewidth=.45,arrow=grid::arrow(ends='both',type='closed',length=grid::unit(1.2,'mm')))+annotate('text',x=xv+.07,y=mean(c(yu,yd)),label=paste0('Delta*',st,' == ',formatC(dv,format='f',digits=2)),parse=TRUE,hjust=0,size=2.55)+scale_colour_manual(values=c('Ramp up'=up,'Ramp down'=down))+scale_fill_manual(values=c('Ramp up'=up,'Ramp down'=down))+scale_x_continuous(breaks=c(0,.5,1),expand=expansion(mult=c(.03,.13)))+scale_y_continuous(breaks=seq(0,1,.25))+coord_cartesian(ylim=c(0,1.02),clip='off')+labs(x='Activation drive',y=ytitle)+th()}
B <- branch('S','Late consolidation state, S',dS,xS); C <- branch('M','Late material-memory tag, M',dM,xM)

# D: matched down-minus-up branch separation
gp <- gaps %>% group_by(activation_amp) %>% summarise(S_mean=mean(S_gap),S_sem=sd(S_gap)/sqrt(n()),M_mean=mean(M_gap),M_sem=sd(M_gap)/sqrt(n()),.groups='drop') %>% pivot_longer(-activation_amp,names_to=c('state','stat'),names_pattern='(.+)_(.+)') %>% pivot_wider(names_from=stat,values_from=value) %>% mutate(state=factor(state,levels=c('S','M'),labels=c('Consolidation state, S','Material-memory tag, M')))
D <- ggplot(gp,aes(activation_amp,mean,colour=state,fill=state))+geom_hline(yintercept=0,linetype='22',colour=grey,linewidth=.38)+geom_ribbon(aes(ymin=mean-sem,ymax=mean+sem),alpha=.15,colour=NA)+geom_line(linewidth=.9)+geom_point(shape=21,size=1.85,fill='white')+scale_colour_manual(values=c('Consolidation state, S'=cs,'Material-memory tag, M'=cm))+scale_fill_manual(values=c('Consolidation state, S'=cs,'Material-memory tag, M'=cm))+scale_x_continuous(breaks=c(0,.5,1))+labs(x='Activation drive',y='Branch separation\n(down - up)')+th()

# E: true trapezoidal signed areas. Explicit x=variable in every summary layer.
al <- ss %>% select(seed,S_signed_area,M_signed_area) %>% pivot_longer(-seed,names_to='metric',values_to='area') %>% mutate(variable=factor(metric,levels=c('S_signed_area','M_signed_area'),labels=c('Consolidation\nstate, S','Material-memory\ntag, M')))
set.seed(20260908)
asum <- al %>% group_by(variable) %>% summarise(median_plot=median(area),ci_low=quantile(replicate(10000,median(sample(area,replace=TRUE))),.025),ci_high=quantile(replicate(10000,median(sample(area,replace=TRUE))),.975),.groups='drop')
atest <- wt %>% filter(metric%in%c('S_signed_area','M_signed_area')) %>% mutate(variable=factor(metric,levels=c('S_signed_area','M_signed_area'),labels=c('Consolidation\nstate, S','Material-memory\ntag, M')),p_label=if_else(one_sided_p<.001,'p < 0.001',paste0('p = ',signif(one_sided_p,2)))) %>% select(variable,n,mean,median_test=median,sd,wilcoxon_W,one_sided_p,p_label)
asum <- left_join(asum,atest,by='variable') %>% mutate(p_label_y=max(al$area)*1.08)
E <- ggplot(al,aes(variable,area,fill=variable))+geom_hline(yintercept=0,linetype='22',colour=grey,linewidth=.38)+geom_violin(width=.72,alpha=.38,colour=NA,trim=FALSE)+geom_jitter(width=.075,shape=21,size=.75,stroke=.15,fill='white',colour=alpha(ink,.55),alpha=.68)+geom_errorbar(data=asum,aes(x=variable,ymin=ci_low,ymax=ci_high),inherit.aes=FALSE,width=.1,linewidth=.65,colour=ink)+geom_point(data=asum,aes(x=variable,y=median_plot),inherit.aes=FALSE,shape=21,size=2.15,stroke=.65,fill='white',colour=ink)+geom_text(data=asum,aes(x=variable,y=p_label_y,label=p_label),inherit.aes=FALSE,size=2.45,colour=ink)+scale_fill_manual(values=c('Consolidation\nstate, S'=cs,'Material-memory\ntag, M'=cm),guide='none')+scale_y_continuous(labels=number_format(accuracy=.01))+coord_cartesian(ylim=c(min(-.02,min(al$area)),max(asum$p_label_y)*1.08),clip='off')+labs(x=NULL,y='Per-seed signed hysteresis area\n(trapezoidal down - up)')+th()+theme(legend.position='none',axis.text.x=element_text(size=7.7,lineheight=.92))

P <- (A|B|C)/(patchwork::plot_spacer()|D|E)+plot_layout(widths=c(.78,1,1),heights=c(1,1),guides='collect')&theme(legend.position='top')

# Export. Base pdf() avoids the broken cairo DLL on this macOS installation.
log <- tibble(panel=character(),format=character(),status=character(),message=character())
write_file <- function(panel,stem,fmt,w,h){f<-file.path(OUT,fmt,paste0(stem,'.',fmt)); z<-tryCatch({if(fmt=='pdf')ggsave(f,panel,device=grDevices::pdf,width=w,height=h,units='mm',bg='white');if(fmt=='png')ggsave(f,panel,device=if(have_ragg)ragg::agg_png else grDevices::png,width=w,height=h,units='mm',dpi=600,bg='white');if(fmt=='svg')ggsave(f,panel,device=if(have_svg)svglite::svglite else grDevices::svg,width=w,height=h,units='mm',bg='white');if(fmt=='tiff')ggsave(f,panel,device=if(have_ragg)ragg::agg_tiff else grDevices::tiff,width=w,height=h,units='mm',dpi=600,compression='lzw',bg='white');if(!file.exists(f)||file.info(f)$size==0)stop('empty output');list(ok=TRUE,msg='')},error=function(e){if(file.exists(f))file.remove(f);list(ok=FALSE,msg=conditionMessage(e))});log<<-bind_rows(log,tibble(panel=stem,format=fmt,status=ifelse(z$ok,'OK','FAILED'),message=z$msg));z$ok}
export <- function(panel,stem,w=82,h=68){r<-sapply(c('pdf','png','svg','tiff'),function(x)write_file(panel,stem,x,w,h));cat(sprintf('%-38s PDF:%s PNG:%s SVG:%s TIFF:%s\n',stem,ifelse(r[1],'OK','FAIL'),ifelse(r[2],'OK','FAIL'),ifelse(r[3],'OK','FAIL'),ifelse(r[4],'OK','FAIL')))}
export(A,'Figure4A_activation_protocol');export(B,'Figure4B_consolidation_state_S');export(C,'Figure4C_material_memory_tag_M');export(D,'Figure4D_branch_separation');export(E,'Figure4E_signed_hysteresis_area');export(P,'Figure4_combined_preview',190,125)
write_csv(sp,file.path(OUT,'plotted_data','Figure4_BC_trajectory_data.csv'));write_csv(w,file.path(OUT,'plotted_data','Figure4_mean_branch_gaps.csv'));write_csv(gp,file.path(OUT,'plotted_data','Figure4D_branch_separation_data.csv'));write_csv(al,file.path(OUT,'plotted_data','Figure4E_seed_signed_area_data.csv'));write_csv(asum,file.path(OUT,'plotted_data','Figure4E_area_summary.csv'));write_csv(log,file.path(OUT,'Figure4_R_export_log.csv'));writeLines(capture.output(sessionInfo()),file.path(OUT,'Figure4_R_sessionInfo.txt'))
cat(sprintf('\nFigure 4 complete: Delta S = %.3f; Delta M = %.3f.\n',dS,dM));print(atest);print(log%>%count(format,status,name='n_files'));cat('Output: ',normalizePath(OUT,mustWork=FALSE),'\n',sep='')
